<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientIsResourceServerAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientIsResourceServerAccessor trait.
 *
 * Covers null default, string/VO assignment via withIsResourceServer,
 * getIsResourceServer/isResourceServer accessors, and isIsResourceServerChanged with/without original.
 */
class TrustedClientIsResourceServerAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withIsResourceServer creates a new instance with the IsResourceServer set
     * from a string value, and getIsResourceServer returns the primitive string.
     */
    public function testWithIsResourceServerFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIsResourceServerAccessorUnitTest();

        // Act
        $result = $holder->withIsResourceServer(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isIsResourceServer());
    }
    /**
     * Asserts that withisResourceServer has access to the value object
     * from a string value, and getIsResourceServer returns the primitive string.
     */
    public function testWithIsResourceServerFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIsResourceServerAccessorUnitTest();

        // Act
        $result = $holder->withIsResourceServer(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isResourceServer()->value());
    }
    public function testChangedIsResourceServer(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientIsResourceServerAccessorUnitTest()->withIsResourceServer(true);
        $original = $holder->withIsResourceServer(true);
        $same = $holder->withIsResourceServer(true);
        $modified = $holder->withIsResourceServer(false);

        // Act
        $withSame = $original->isIsResourceServerChanged($same);
        $withDiferent = $original->isIsResourceServerChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientIsResourceServerAccessorUnitTest
{
    use TrustedClientIsResourceServerAccessor;
}
